<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Otter Community Events</title>
<style>
:root{color-scheme:dark;--gold:#f6cc71;--aqua:#67e5d6;--speed:6s}*{box-sizing:border-box}html,body{margin:0;background:transparent;color:#edfafa;font:18px 'Segoe UI',sans-serif;overflow:hidden}main{width:min(100vw,900px);padding:14px}.hidden{display:none!important}.panel{position:relative;border:1px solid #77d6d86b;border-radius:26px;background:linear-gradient(145deg,#071e35f2,#063d4aef);overflow:hidden;box-shadow:0 10px 30px #001b2c66}header{padding:20px 24px 8px;display:flex;justify-content:space-between;gap:12px;align-items:center}h1,h2,p{margin:0}h1{font-size:clamp(21px,4vw,32px);color:var(--gold);letter-spacing:.3px}h2{font-size:26px;color:var(--gold)}.eyebrow{color:var(--aqua);font-size:12px;font-weight:700;letter-spacing:3px;margin-bottom:8px}.badge{border:1px solid #69ddd855;border-radius:30px;padding:7px 13px;color:var(--aqua);white-space:nowrap;font-size:14px}.scene{height:220px;position:relative;background:radial-gradient(ellipse at 75% 65%,#31857b5e,transparent 60%)}.sea{position:absolute;width:100%;height:100%;inset:0}.chamber{position:absolute;right:5%;bottom:12px;width:44%;height:205px;filter:drop-shadow(0 6px 20px #003844)}.lid{transform-origin:150px 107px;transition:transform 1.3s ease}.success .lid{transform:translateY(-28px) rotate(-14deg)}.treasure-glow{opacity:.15;transition:opacity 1s}.success .treasure-glow{opacity:1}.raiding .chamber{animation:rumble 450ms ease-in-out infinite}.failed .chamber{filter:grayscale(.7);animation:rumble .3s 3}.crew{position:absolute;left:4%;bottom:18px;width:53%;display:flex;align-items:flex-end;justify-content:center}.otter{width:76px;height:106px;margin-left:-22px;animation:swim 2.4s ease-in-out infinite;animation-delay:calc(var(--i)*-.27s);filter:drop-shadow(0 5px 5px #001d32)}.otter:first-child{margin-left:0}.otter svg{width:100%;height:100%}.otter.new{animation:arrive .7s ease-out,swim 2.4s .7s infinite}.raiding .crew{animation:approach var(--speed) ease-in-out both}.success .otter{animation:celebrate .7s ease-in-out infinite alternate}.failed .crew{opacity:.65;transform:translateX(-20px)}.bubble{position:absolute;bottom:0;border:1px solid #76e4df70;border-radius:50%;width:9px;height:9px;animation:bubble 5s linear infinite;left:var(--x);animation-delay:var(--delay)}.pearls{position:absolute;right:16%;bottom:65px;pointer-events:none}.pearl{display:block;position:absolute;width:12px;height:12px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#fff,#c5e7e5 50%,#e9c769);opacity:0}.success.effects .pearl{animation:pearl 1.7s ease-out infinite;animation-delay:calc(var(--i)*.09s)}.summary{padding:4px 24px 18px;position:relative}.headline{font-size:23px;font-weight:700;color:var(--gold);min-height:30px}.detail{color:#b9d9de;font-size:15px;margin-top:7px;line-height:1.5}.metrics{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}.metric{border:1px solid #6acac62d;background:#031d2d80;border-radius:12px;padding:8px 13px;font-size:14px}.metric strong{color:var(--aqua)}.names{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px;max-height:76px;overflow:hidden}.name{font-size:12px;background:#1c52606e;border:1px solid #60b7bb44;border-radius:15px;padding:5px 9px}.hiding{animation:fadeOut 1s ease forwards}.enter{animation:fadeIn .6s ease}.progress{height:7px;background:#032c38;margin-top:12px;border-radius:20px;overflow:hidden}.progress>i{display:block;height:100%;background:linear-gradient(90deg,var(--aqua),var(--gold));transition:width .3s}.event{padding:24px}.event progress{width:100%;height:24px;accent-color:#67e5d6;margin-top:14px}.hot{margin-top:10px;border-radius:16px;padding:12px 18px;background:linear-gradient(100deg,#442807ee,#122d3dee);border:1px solid #f3b95788;font-weight:600;font-size:15px}.urgent{animation:urgent 1s ease-in-out infinite alternate}.preview{position:relative;z-index:10;margin:8px;padding:12px;background:#092b39;border:1px dashed var(--gold);border-radius:10px;font-size:12px}.preview button{margin:4px;padding:7px 10px;background:#174b5c;color:#fff;border:1px solid #6ab5b8;border-radius:6px}.testflag{color:var(--gold);font-weight:bold}.blankhint{font-size:13px;color:#a4c5cb}.defs{position:absolute;width:0;height:0;overflow:hidden}
@keyframes swim{50%{transform:translateY(-9px) rotate(-4deg)}}@keyframes arrive{from{opacity:0;transform:translate(-60px,25px)}to{opacity:1;transform:none}}@keyframes approach{0%{transform:translateX(0)}55%,100%{transform:translateX(28%)}}@keyframes rumble{25%{transform:translateX(-2px)}75%{transform:translateX(2px)}}@keyframes celebrate{to{transform:translateY(-15px) rotate(5deg)}}@keyframes bubble{to{transform:translateY(-230px);opacity:0}}@keyframes pearl{0%{opacity:0;transform:translate(0,0)}25%{opacity:1}100%{opacity:0;transform:translate(calc(var(--dx)*1px),-150px)}}@keyframes fadeOut{to{opacity:0;transform:translateY(12px)}}@keyframes fadeIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}@keyframes urgent{to{border-color:#ff7b45;color:#ffd396}}@media(prefers-reduced-motion:reduce){.otter,.crew,.bubble,.pearl,.chamber,.urgent{animation:none!important}}@media(max-width:650px){main{padding:8px}header{padding:16px 18px 6px}.scene{height:185px}.chamber{height:170px}.otter{width:60px;height:92px}.summary{padding:4px 18px 16px}.headline{font-size:20px}}
</style>
<svg class="defs" aria-hidden="true"><defs><symbol id="otter-pirate" viewBox="0 0 90 130"><path d="M62 88Q93 116 66 124Q77 107 49 99" fill="#83502e"/><ellipse cx="45" cy="82" rx="27" ry="35" fill="#a97141"/><ellipse cx="45" cy="83" rx="18" ry="26" fill="#e8c79b"/><ellipse cx="22" cy="81" rx="9" ry="16" fill="#83502e" transform="rotate(30 22 81)"/><ellipse cx="69" cy="81" rx="9" ry="16" fill="#83502e" transform="rotate(-30 69 81)"/><circle cx="24" cy="37" r="10" fill="#83502e"/><circle cx="65" cy="37" r="10" fill="#83502e"/><ellipse cx="45" cy="47" rx="28" ry="25" fill="#af7b4b"/><ellipse cx="45" cy="57" rx="19" ry="13" fill="#eed5af"/><circle cx="34" cy="45" r="3" fill="#102534"/><path d="M54 45h9" stroke="#102534" stroke-width="4"/><ellipse cx="46" cy="52" rx="5" ry="3" fill="#352820"/><path d="M40 60q6 6 12 0M20 53l-12-3m13 8-13 1m61-6 12-3m-12 8 13 1" fill="none" stroke="#704b38" stroke-width="2"/><path d="M14 30Q24 23 27 10Q45 22 64 10Q68 25 78 30Z" fill="#122333" stroke="#f4cb75" stroke-width="2"/><path d="M41 25l9-8m-9 0 9 8" stroke="#fff2cb" stroke-width="2"/><circle cx="45" cy="83" r="7" fill="#d4fff3" opacity=".9"/></symbol></defs></svg>
<div id="preview" class="preview hidden"><span class="testflag">LOKALE VORSCHAU – Mockdaten, keine Perlen oder Chatmeldungen</span><div id="buttons"></div><span class="blankhint">Eigene austauschbare SVG-Platzhalter · Vorschau 900 × 600 empfohlen</span></div>
<main><section id="heist" class="panel hidden" aria-live="polite"><header><div><div class="eyebrow">FUNJII OTTER RPG · COMMUNITY HEIST</div><h1 id="title"></h1></div><span class="badge" id="phase"></span></header>
<div class="scene"><svg class="sea" viewBox="0 0 900 230" preserveAspectRatio="none"><path d="M0 200q100-35 200 0t200 0t200 0t300 0v40H0" fill="#0a4c5680"/><path d="M12 220q35-42 5-85m35 85q-20-70 10-105m765 105q-35-70 0-110m20 110q40-45 15-85" fill="none" stroke="#378b7790" stroke-width="9"/><path d="M600 220V100Q710-40 820 100v120M620 220V108Q710-12 800 108v112" fill="#062a3b" stroke="#58828a" stroke-width="12"/></svg>
