<div id="crew" class="crew"></div><div id="pearls" class="pearls"></div></div>
<div class="summary"><p id="headline" class="headline"></p><p id="detail" class="detail"></p><div class="metrics"><span class="metric">Crew: <strong id="count"></strong></span><span class="metric" id="jackpot"></span><span class="metric" id="entry"></span></div><div class="progress"><i id="timebar"></i></div><div id="names" class="names"></div></div></section>
